<script setup>import { onMounted,ref } from 'vue';import { api } from '../api/oa';const items=ref([]),selected=ref(null);onMounted(async()=>items.value=await api.notices())</script>
<template><div class="page safe-top"><van-nav-bar title="企业公告" left-arrow @click-left="$router.back()"/><section v-for="item in items" :key="item.id" class="card" @click="selected=item"><div class="notice-head"><span v-if="item.pinned" class="tag">置顶</span><span class="muted">{{item.publishTime?.slice(0,10)}}</span></div><h3>{{item.title}}</h3><p>{{item.content}}</p><div class="muted">发布人：{{item.publisher}}</div></section><van-popup v-model:show="selected" round position="bottom" :style="{height:'65%'}"><article v-if="selected" class="article"><h2>{{selected.title}}</h2><div class="muted">{{selected.publisher}} · {{selected.publishTime?.replace('T',' ').slice(0,16)}}</div><p>{{selected.content}}</p></article></van-popup></div></template>
<style scoped>.van-nav-bar{background:transparent;margin:-8px -16px 14px}.notice-head{display:flex;justify-content:space-between}.card h3{margin:12px 0 7px}.card p{color:#586b72;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.article{padding:28px 22px}.article h2{color:#183b44}.article p{white-space:pre-wrap;line-height:1.9;color:#465d65}</style>
